var t=`1313-dulce-de-leche-flan`;var a=`world-1313`;var n=`AR`;var r=`south-america`;var l=4;var o=256;var c={en:`Dulce de Leche Flan`,ua:`Флан із дульсе де лече`};var d={en:`Dulce de Leche Flan is a dish from Argentina featuring chicken egg, whole cow milk. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Флан із дульсе де лече, страва кухні країни Аргентина з такими основними складниками: куряче яйце, цільне коров'яче молоко. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var s=[{en:`Heat the listed ingredients over moderate heat, stirring only as needed, for about 9 minutes until amber and fragrant.`,ua:`Нагрівайте зазначені складники на помірному вогні приблизно 9 хвилин до бурштинового кольору й аромату, помішуючи за потреби.`,t:[`caramelizing-sugar`],m:9,i:[[`white-granulated-sugar`,160,`g`],[`water`,60,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`chicken-egg`,5,`pcs`],[`dulce-de-leche`,320,`g`],[`whole-cow-milk`,550,`ml`],[`vanilla-extract`,6,`ml`]]},{en:`Place the caramel-coated flan dish in a larger tray of hot water and bake gently at 160°C until just set; cool then chill thoroughly.`,ua:`Поставте форму з фланом у більшу форму з гарячою водою й повільно випікайте при 160°C до застигання; остудіть та добре охолодіть.`,t:[`poaching`],m:55,i:[]},{en:`Refrigerate the prepared mixture for about 180 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 180 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:180,i:[]}];var h={slug:t,id:a,country:`AR`,region:r,servings:4,minutes:256,title:c,text:d,steps:s};export{n as country,h as default,a as id,o as minutes,r as region,l as servings,t as slug,s as steps,d as text,c as title};